INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('ae156f2f-3f29-464f-aab8-2c6323aa5d87', 'https://www.jornada.com.mx/2026/02/24/politica/005n2pol?partner=rss', 'Alcalde de Vallarta da la cara luego de 27 horas', 'Durante la ola de violencia criminal que el domingo azotó este puerto, uno de los principales destinos turísticos del país, en reacción a la muerte de El Mencho, “de manera preliminar más de 200 vehíc', '/logo.png', 'Hoy', 'Durante la ola de violencia criminal que el domingo azotó este puerto, uno de los principales destinos turísticos del país, en reacción a la muerte de El Mencho, “de manera preliminar más de 200 vehículos resultaron afectados (quemados) en distintos puntos del municipio”, informó el alcalde Luis Ernesto Munguía, quien ayer dio la cara, 27 horas después de los acontecimientos. Además, 70 tiendas de autoservicio y establecimientos comerciales fueron incendiados.', 'POLITICA', 464);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('ae156f2f-3f29-464f-aab8-2c6323aa5d87', 'API', 'Alcalde de Vallarta da la cara luego de 27 horas', 'Durante la ola de violencia criminal que el domingo azotó este puerto, uno de los principales destinos turísticos del país, en reacción a la muerte de El Mencho, “de manera preliminar más de 200 vehículos resultaron afectados (quemados) en distintos puntos del municipio”, informó el alcalde Luis Ernesto Munguía, quien ayer dio la cara, 27 horas después de los acontecimientos. Además, 70 tiendas de autoservicio y establecimientos comerciales fueron incendiados.', 'Alcalde de Vallarta da la cara luego de 27 horas', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('6c0aae6b-0d16-4d05-b1c5-e3e054e41889', 'https://www.jornada.com.mx/2026/02/24/politica/008n1pol?partner=rss', 'AICM reforzó seguridad; operó sin contratiempos', 'El Aeropuerto Internacional de la Ciudad de México (AICM) reforzó la seguridad en sus instalaciones, incluso con binomios caninos, luego de que integrantes del Ejército Mexicano abatieron el domingo a', '/logo.png', 'Hoy', 'El Aeropuerto Internacional de la Ciudad de México (AICM) reforzó la seguridad en sus instalaciones, incluso con binomios caninos, luego de que integrantes del Ejército Mexicano abatieron el domingo a Nemesio Rubén Oseguera Cervantes, El Mencho, capo del cártel Jalisco Nueva Generación (CJNG).', 'POLITICA', 294);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('6c0aae6b-0d16-4d05-b1c5-e3e054e41889', 'API', 'AICM reforzó seguridad; operó sin contratiempos', 'El Aeropuerto Internacional de la Ciudad de México (AICM) reforzó la seguridad en sus instalaciones, incluso con binomios caninos, luego de que integrantes del Ejército Mexicano abatieron el domingo a Nemesio Rubén Oseguera Cervantes, El Mencho, capo del cártel Jalisco Nueva Generación (CJNG).', 'AICM reforzó seguridad; operó sin contratiempos', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('5fc280e6-8a46-41ec-8841-12007ef2e7c0', 'https://www.jornada.com.mx/2026/02/24/politica/017a1pol?partner=rss', 'Felipe Ávila*: El legado de Madero', 'Madero es el padre de la    democracia mexicana, el que construyó sus primeros cimientos: quien creó el primer partido político moderno, quien hizo la primera campaña electoral moderna, quien document', '/logo.png', 'Hoy', 'Madero es el padre de la    democracia mexicana, el que construyó sus primeros cimientos: quien creó el primer partido político moderno, quien hizo la primera campaña electoral moderna, quien documentó por primera vez el fraude electoral y pidió su anulación y quien, al cerrársele las opciones institucionales, decidió llamar al pueblo de México a levantarse en armas contra un gobierno usurpador. La legitimidad que tenía Madero en 1910, como la principal figura política nacional opositora y la hábil conducción de su liderazgo cuando llamó al pueblo a levantarse en armas el 20 de noviembre de ese año, permitió que, en seis meses, la insurrección pusiera fin al largo gobierno de Porfirio Díaz. Madero demostró así que su diagnóstico, expresado en su célebre libro La sucesión presidencial, era preciso. El pueblo de México no sólo estaba apto para la democracia, sino que la quería y estaba dispuesto a luchar para alcanzarla. El triunfo de su revolución era la mejor prueba de ello.', 'POLITICA', 989);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('5fc280e6-8a46-41ec-8841-12007ef2e7c0', 'API', 'Felipe Ávila*: El legado de Madero', 'Madero es el padre de la    democracia mexicana, el que construyó sus primeros cimientos: quien creó el primer partido político moderno, quien hizo la primera campaña electoral moderna, quien documentó por primera vez el fraude electoral y pidió su anulación y quien, al cerrársele las opciones institucionales, decidió llamar al pueblo de México a levantarse en armas contra un gobierno usurpador. La legitimidad que tenía Madero en 1910, como la principal figura política nacional opositora y la hábil conducción de su liderazgo cuando llamó al pueblo a levantarse en armas el 20 de noviembre de ese año, permitió que, en seis meses, la insurrección pusiera fin al largo gobierno de Porfirio Díaz. Madero demostró así que su diagnóstico, expresado en su célebre libro La sucesión presidencial, era preciso. El pueblo de México no sólo estaba apto para la democracia, sino que la quería y estaba dispuesto a luchar para alcanzarla. El triunfo de su revolución era la mejor prueba de ello.', 'Felipe Ávila*: El legado de Madero', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('88598486-bc94-456b-9db1-0c7ac908dc35', 'https://www.jornada.com.mx/2026/02/24/politica/007n1pol?partner=rss', 'México debe aumentar esfuerzos contra los cárteles, amaga Trump', '“¡México debe intensificar sus esfuerzos contra los cárteles y las drogas!”, afirmó ayer el presidente Donald Trump en sus redes sociales, sin mencionar el operativo de fuerzas federales mexicanas que', '/logo.png', 'Hoy', '“¡México debe intensificar sus esfuerzos contra los cárteles y las drogas!”, afirmó ayer el presidente Donald Trump en sus redes sociales, sin mencionar el operativo de fuerzas federales mexicanas que culminó con la muerte de Nemesio Oseguera Cervantes, El Mencho.', 'POLITICA', 264);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('88598486-bc94-456b-9db1-0c7ac908dc35', 'API', 'México debe aumentar esfuerzos contra los cárteles, amaga Trump', '“¡México debe intensificar sus esfuerzos contra los cárteles y las drogas!”, afirmó ayer el presidente Donald Trump en sus redes sociales, sin mencionar el operativo de fuerzas federales mexicanas que culminó con la muerte de Nemesio Oseguera Cervantes, El Mencho.', 'México debe aumentar esfuerzos contra los cárteles, amaga Trump', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('8fe81ee6-392c-437d-a071-32b7f4e0691a', 'https://www.jornada.com.mx/2026/02/24/politica/014n1pol?partner=rss', 'Este mes, la cifra  más alta de contagios de sarampión en  una semana: Salud', 'El registro del brote activo de sarampión señala que se han confirmado 10 mil 634 casos, y entre el 8 y 14 de febrero, aún con datos preliminares, se alcanzó la cifra más alta de afectados en una sema', '/logo.png', 'Hoy', 'El registro del brote activo de sarampión señala que se han confirmado 10 mil 634 casos, y entre el 8 y 14 de febrero, aún con datos preliminares, se alcanzó la cifra más alta de afectados en una semana, con 973, más del triple de los reportados a mediados de abril de 2025.', 'POLITICA', 274);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('8fe81ee6-392c-437d-a071-32b7f4e0691a', 'API', 'Este mes, la cifra  más alta de contagios de sarampión en  una semana: Salud', 'El registro del brote activo de sarampión señala que se han confirmado 10 mil 634 casos, y entre el 8 y 14 de febrero, aún con datos preliminares, se alcanzó la cifra más alta de afectados en una semana, con 973, más del triple de los reportados a mediados de abril de 2025.', 'Este mes, la cifra  más alta de contagios de sarampión en  una semana: Salud', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('c80c7141-8358-4047-a696-b50ed911d953', 'https://www.jornada.com.mx/2026/02/24/politica/005n4pol?partner=rss', 'Activos, sólo 7 bloqueos viales en tierra jalisciense', 'Al menos siete bloqueos carreteros seguían activos ayer en Jalisco, de los 65 instalados el domingo por integrantes del cártel Jalisco Nueva Generación (CJNG) tras la muerte de su líder, Nemesio Osegu', '/logo.png', 'Hoy', 'Al menos siete bloqueos carreteros seguían activos ayer en Jalisco, de los 65 instalados el domingo por integrantes del cártel Jalisco Nueva Generación (CJNG) tras la muerte de su líder, Nemesio Oseguera, El Mencho.', 'POLITICA', 215);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('c80c7141-8358-4047-a696-b50ed911d953', 'API', 'Activos, sólo 7 bloqueos viales en tierra jalisciense', 'Al menos siete bloqueos carreteros seguían activos ayer en Jalisco, de los 65 instalados el domingo por integrantes del cártel Jalisco Nueva Generación (CJNG) tras la muerte de su líder, Nemesio Oseguera, El Mencho.', 'Activos, sólo 7 bloqueos viales en tierra jalisciense', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('19bcb7f3-a592-4f3e-828e-3a699b15cd54', 'https://www.jornada.com.mx/2026/02/24/politica/012n1pol?partner=rss', '“Inviable”, crear comisión de la verdad para el caso Iguala: CNDH', 'A pesar de que un tribunal colegiado ordenó integrar la comisión de la verdad del caso Iguala, la Comisión Nacional de los Derechos Humanos (CNDH) señaló la imposibilidad de hacerlo, entre otras cosas', '/logo.png', 'Hoy', 'A pesar de que un tribunal colegiado ordenó integrar la comisión de la verdad del caso Iguala, la Comisión Nacional de los Derechos Humanos (CNDH) señaló la imposibilidad de hacerlo, entre otras cosas porque, dijo, actualmente se encuentra en proceso de conclusión un nuevo expediente de queja por la inconformidad de los familiares de los estudiantes desaparecidos y normalistas sobrevivientes respecto del contenido de la recomendación 15VG/2018.', 'POLITICA', 448);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('19bcb7f3-a592-4f3e-828e-3a699b15cd54', 'API', '“Inviable”, crear comisión de la verdad para el caso Iguala: CNDH', 'A pesar de que un tribunal colegiado ordenó integrar la comisión de la verdad del caso Iguala, la Comisión Nacional de los Derechos Humanos (CNDH) señaló la imposibilidad de hacerlo, entre otras cosas porque, dijo, actualmente se encuentra en proceso de conclusión un nuevo expediente de queja por la inconformidad de los familiares de los estudiantes desaparecidos y normalistas sobrevivientes respecto del contenido de la recomendación 15VG/2018.', '“Inviable”, crear comisión de la verdad para el caso Iguala: CNDH', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('e2089a83-281b-462e-83d9-f6e25ebf861e', 'https://www.jornada.com.mx/2026/02/24/politica/002n1pol?partner=rss', 'Hay gobierno; las prioridades son la paz y la seguridad: Sheinbaum', '“La gente puede saber que estamos trabajando todos los días por su seguridad y por la paz, y que hay gobierno y hay Estado mexicano”, enfatizó la presidenta Claudia Sheinbaum Pardo.', '/logo.png', 'Hoy', '“La gente puede saber que estamos trabajando todos los días por su seguridad y por la paz, y que hay gobierno y hay Estado mexicano”, enfatizó la presidenta Claudia Sheinbaum Pardo.', 'POLITICA', 181);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('e2089a83-281b-462e-83d9-f6e25ebf861e', 'API', 'Hay gobierno; las prioridades son la paz y la seguridad: Sheinbaum', '“La gente puede saber que estamos trabajando todos los días por su seguridad y por la paz, y que hay gobierno y hay Estado mexicano”, enfatizó la presidenta Claudia Sheinbaum Pardo.', 'Hay gobierno; las prioridades son la paz y la seguridad: Sheinbaum', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('d36dafc0-193c-4280-8379-333de8fc064a', 'https://www.jornada.com.mx/2026/02/24/politica/020a2pol?partner=rss', 'José Blanco: El imperio contraataca', 'La 62 Conferencia de    Seguridad de Múnich tuvo méritos agradecibles. El pasado 13 de febrero, Marco Rubio dio ahí un discurso exhibicionista explicando el alcance del proyecto MAGA. Instalado con na', '/logo.png', 'Hoy', 'La 62 Conferencia de    Seguridad de Múnich tuvo méritos agradecibles. El pasado 13 de febrero, Marco Rubio dio ahí un discurso exhibicionista explicando el alcance del proyecto MAGA. Instalado con naturalidad en la dialéctica del amo y el esclavo, desde un supremacismo blanco sin inhibiciones, se abrió la gabardina para mostrar sus armas a los infantes: sus congéneres europeos, a los que ve disminuidos.', 'POLITICA', 407);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('d36dafc0-193c-4280-8379-333de8fc064a', 'API', 'José Blanco: El imperio contraataca', 'La 62 Conferencia de    Seguridad de Múnich tuvo méritos agradecibles. El pasado 13 de febrero, Marco Rubio dio ahí un discurso exhibicionista explicando el alcance del proyecto MAGA. Instalado con naturalidad en la dialéctica del amo y el esclavo, desde un supremacismo blanco sin inhibiciones, se abrió la gabardina para mostrar sus armas a los infantes: sus congéneres europeos, a los que ve disminuidos.', 'José Blanco: El imperio contraataca', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);
INSERT INTO ARTICULOS_ORIGINALES (ID, URL, TITULO, DESCRIPCION, URL_IMAGEN, FECHA, CONTENIDO, CATEGORIA, LONGITUD) VALUES ('d0791469-b788-4354-9b12-c23b1ac26d64', 'https://www.jornada.com.mx/2026/02/24/politica/012n2pol?partner=rss', 'Agremiados de la CROC podrán acceder a Leche para el Bienestar: Sader', 'La Secretaría de Agricultura y Desarrollo Rural (Sader) firmó un convenio de colaboración con la Confederación Revolucionaria de Obreros y Campesinos (CROC), que abre la oportunidad de integrar al sec', '/logo.png', 'Hoy', 'La Secretaría de Agricultura y Desarrollo Rural (Sader) firmó un convenio de colaboración con la Confederación Revolucionaria de Obreros y Campesinos (CROC), que abre la oportunidad de integrar al sector obrero y campesino al padrón de beneficiarios del programa de Abasto Social de Leche para el Bienestar.', 'POLITICA', 307);
INSERT INTO REVISION_CONTENIDO (ID_ORIGEN, TIPO_ORIGEN, TITULO_PROPUESTO, CONTENIDO_PROPUESTO, DESCRIPCION_PROPUESTA, SITIO_DESTINO, CATEGORIA, ESTADO, URL_IMAGEN, FB_REQUERIDO) VALUES ('d0791469-b788-4354-9b12-c23b1ac26d64', 'API', 'Agremiados de la CROC podrán acceder a Leche para el Bienestar: Sader', 'La Secretaría de Agricultura y Desarrollo Rural (Sader) firmó un convenio de colaboración con la Confederación Revolucionaria de Obreros y Campesinos (CROC), que abre la oportunidad de integrar al sector obrero y campesino al padrón de beneficiarios del programa de Abasto Social de Leche para el Bienestar.', 'Agremiados de la CROC podrán acceder a Leche para el Bienestar: Sader', 'noticiasobjetivo,mexicoinformado,bitacoraurbana,nodoinformativo,cbnnoticias,radiocinconoticias,centralmexico,reportecentralmx,tvmexico,verticenoticias', 'POLITICA', 'PENDIENTE', '/logo.png', 0);